<?php
$money=fn(int $value): string=>'R$ '.number_format($value/100,2,',','.');
$titles=['stock'=>'Visão geral do estoque','moves'=>'Movimentações','customers'=>'Clientes'];
$title=$titles[$section]??'Gestão';
$tracked=array_values(array_filter($products,fn($product)=>$product['stock_quantity']!==null));
$lowStock=array_values(array_filter($tracked,fn($product)=>(int)$product['stock_quantity']<=5));
$stockUnits=array_sum(array_map(fn($product)=>(int)$product['stock_quantity'],$tracked));
$stockValue=array_sum(array_map(fn($product)=>(int)$product['stock_quantity']*(int)$product['price_cents'],$tracked));
$customerOrders=array_sum(array_map(fn($customer)=>(int)$customer['order_count'],$customers));
$customerRevenue=array_sum(array_map(fn($customer)=>(int)$customer['lifetime_value_cents'],$customers));
$averageCustomer=$customers?(int)round($customerRevenue/count($customers)):0;
?>
