<?php if($section==='moves'):?><?php if(!$movements):?><tr><td colspan="7"><div class="estado-vazio compacto"><b>Sem movimentações</b><p>O histórico aparecerá após o primeiro ajuste.</p></div></td></tr><?php else:foreach($movements as$movement):?><tr><td><?= e(date('d/m/Y H:i',strtotime($movement['created_at']))) ?></td><td><b><?= e($movement['product_name']) ?></b></td><td><span class="etiqueta <?= $movement['movement_type']==='entry'?'verde':($movement['movement_type']==='exit'?'vermelho':'amarelo') ?>"><?= e(['entry'=>'Entrada','exit'=>'Saída','adjustment'=>'Ajuste'][$movement['movement_type']]??$movement['movement_type']) ?></span></td><td><?= (int)$movement['quantity'] ?></td><td><b><?= (int)$movement['balance_after'] ?></b></td><td><?= e($movement['reference']??'—') ?></td><td><?= e($movement['notes']??'—') ?></td></tr><?php endforeach;endif;?>
<?php else:?><?php if(!$products):?><tr><td colspan="7"><div class="estado-vazio compacto"><b>Estoque vazio</b><p>Cadastre produtos para iniciar o controle.</p></div></td></tr><?php else:foreach($products as$product):$quantity=$product['stock_quantity'];$isLow=$quantity!==null&&(int)$quantity<=5;?><tr><td><b><?= e($product['name']) ?></b><small><?= $product['active']?'Produto ativo':'Produto inativo' ?></small></td><td><?= e($product['category_name']) ?></td><td><?= $quantity===null?'Ilimitado':(int)$quantity.' un.' ?></td><td>5 un.</td><td><?= $quantity===null?'—':$money((int)$quantity*(int)$product['price_cents']) ?></td><td><span class="etiqueta <?= $quantity===null||!$isLow?'verde':((int)$quantity===0?'vermelho':'amarelo') ?>"><?= $quantity===null?'Sem controle':((int)$quantity===0?'Esgotado':($isLow?'Baixo':'OK')) ?></span></td><td><a class="botao pequeno" href="/admin?section=products">Editar</a></td></tr><?php endforeach;endif;?><?php endif;?></tbody></table></div><footer class="rodape-tabela"><span>Exibindo <?= $section==='moves'?count($movements):count($products) ?> resultado(s)</span><span>Dados reais da loja</span></footer></article>

