<article class="cartao cartao-tabela-administrativa"><div class="envoltorio-tabela"><table><thead><tr><th>Cliente</th><th>Telefone</th><th>E-mail</th><th>Pedidos</th><th>Total comprado</th><th>Ticket médio</th></tr></thead><tbody><?php if(!$customers):?><tr><td colspan="6"><div class="estado-vazio compacto"><b>Nenhum cliente ainda</b><p>Os clientes aparecerão automaticamente após pedidos válidos.</p></div></td></tr><?php else:foreach($customers as$customer):?><tr><td><b><?= e($customer['name']) ?></b></td><td><?= e($customer['phone']) ?></td><td><?= e($customer['email']?:'—') ?></td><td><span class="etiqueta"><?= (int)$customer['order_count'] ?></span></td><td><b><?= $money((int)$customer['lifetime_value_cents']) ?></b></td><td><?= $money((int)$customer['order_count']>0?(int)round((int)$customer['lifetime_value_cents']/(int)$customer['order_count']):0) ?></td></tr><?php endforeach;endif;?></tbody></table></div><footer class="rodape-tabela"><span>Exibindo <?= count($customers) ?> resultado(s)</span><span>Valor médio <?= $money($averageCustomer) ?></span></footer></article>
